            const element = document.querySelector(`[data-col="${coord.col}"][data-row="${i}"]`);

            if (element) {
                // Check if the cell has content or formula
                let value = '';
                let formula = null;

                if (element.textContent.trim() !== '') {
                    const text = element.textContent.trim();
                    if (text.startsWith('=')) {
                        formula = text;
                        value = getFormulaValue(formula); // Calculate and store the resulting value
