        const state = JSON.parse(stateJson);
        Object.keys(state.cells).forEach(coordKey => {
            const coord = parseCoord(coordKey);
            const cellData = state.cells[coordKey];
            const element = getCellElement(coord);

            if (element) {
                if (cellData.formula) {
                    // Restore formula and recalculate value
                    element.textContent = cellData.formula;
                    updateCellUI(coord); // This will trigger calculation
                } else if (cellData.value !== null && cellData.value !== undefined) {
                    // Restore plain value
                    element.textContent = cellData.value;
                    updateCellUI(coord);
                }
            }
        });
        console.log('State loaded successfully.');
        return true;

    } catch (e) {
        console.error('Error loading state:', e);
        localStorage.removeItem('spreadsheetState'); // Clear corrupted state
        return false;
    }
}
