```js
function updateCellUI(coord) {
    // ... (No changes needed for this function based on the structural bug report)
    const element = getCellElement(coord);
    if (!element) return;

    // 1. Clear previous content and formula tracking
    element.removeAttribute('contenteditable');
    element.textContent = '';
    element.dataset.formula = null;

    // 2. Set the new value/formula
    const { value, formula } = getCellData(coord);

    if (formula) {
        element.textContent = formula;
        element.setAttribute('contenteditable', 'true');
        element.dataset.formula = formula;
    } else if (value !== null && value !== undefined) {
        element.textContent = String(value);
        element.setAttribute('contenteditable', 'true');
        element.dataset.formula = null;
    } else {
        // Empty cell
        element.textContent = '';
        element.removeAttribute('contenteditable');
        element.dataset.formula = null;
    }

    // 3. Trigger recalculation for dependencies
    recalculateDependencies(coord);
}
