### FUNCION: calculateFormula
```js
function calculateFormula(formulaString) {
    // ... (No changes needed for this function based on the structural bug report)
    try {
        let expression = formulaString;

        // 1. Replace Excel functions with JS equivalents and handle syntax differences
        expression = expression.replace(/SUMA\(([^)]+)\)/g, 'sum('); // SUMA(A1:B2) -> sum(A1:B2)
        expression = expression.replace(/SUMA\(\s*([^)]+)\s*\)/g, 'sum($1)'); // Handle potential whitespace issues

        // 2. Replace semicolons (;) used as list separators in Excel with commas (,) for JS eval compatibility
        expression = expression.replace(/;/g, ',');

        // 3. Evaluate the mathematical expression using Function constructor for safety and scope control
        const keys = ['Math', 'Date']; // Include necessary global objects if needed
        const values = [window.Math, window.Date];

        // Create a function that evaluates the string expression
        const evaluator = new Function(...keys, `return (${expression});`);

        let result = evaluator(...values);

        if (isNaN(result) || !isFinite(result)) {
            return 'Error';
        }
        return result;

    } catch (e) {
        console.error("Formula calculation error:", e);
        return 'Error';
    }
}
