function recalculateDependencies(changedCoord) {
    // ... (No changes needed for this function based on the structural bug report)
    const changedCol = parseInt(changedCoord.col.toUpperCase().substring(0, 1)) - 1;
    const changedRow = parseInt(changedCoord.row);

    if (isNaN(changedCol) || isNaN(changedRow)) return;

    // Iterate over all cells to check if they depend on the changed coordinate
    for (let i = 1; i <= MAX_ROWS; i++) {
        for (let j = 0; j < MAX_COLS; j++) {
            const coord = getCoord(j, i);
            const element = getCellElement(coord);

            if (element && element.dataset.formula) {
                const formulaString = element.dataset.formula;
                // Simple check: if the coordinate is mentioned in the formula string
                if (formulaString.includes(`${coord.col}:${changedCoord.col}`) || 
                    formulaString.includes(changedCoord.col) && formulaString.includes(changedRow)) {

                    const newValue = calculateFormula(formulaString);
                    updateCellUI(coord); // Recalculate and update the UI for this dependency
                }
            }
        }
    }
}
