function initializeGrid() {
    // ... (No changes needed for this function based on the structural bug report)
    const gridArea = document.getElementById('grid-area');
    if (!gridArea) return;

    // Clear existing content
    gridArea.innerHTML = '';

    for (let i = 1; i <= MAX_ROWS; i++) {
        // Create the row label element (the number 'i')
        const rowLabel = document.createElement('div');
        rowLabel.className = 'row-label';
        rowLabel.dataset.row = i;
        rowLabel.textContent = i;
        rowLabel.addEventListener('click', () => handleRowNumberClick(event));

        // Create the container for cells in this row (A1, B1, etc.)
        const rowCellsContainer = document.createElement('div');
        rowCellsContainer.className = 'cell-grid';
        rowCellsContainer.dataset.row = i; // Attach row data attribute to the container

        for (let j = 0; j < MAX_COLS; j++) {
            const colLetter = String.fromCharCode('A'.charCodeAt(0) + j);
            const cell = document.createElement('div');
            cell.className = 'cell';
            cell.dataset.col = colLetter;
            cell.dataset.row = i;
            cell.textContent = ''; // Empty initial content
            cell.addEventListener('click', (e) => handleCellClick(e));
            rowCellsContainer.appendChild(cell);
        }

        // Append the row label and its cells container to the grid area
        gridArea.appendChild(rowLabel);
        gridArea.appendChild(rowCellsContainer);
    }
}
