    for (let r = 1; r <= NUM_ROWS; r++) {
        for (let c = 0; c < NUM_COLUMNS; c++) {
            const coord = getCoord(c, r);
            if (spreadsheetData[coord]) {
                updateCellUI(coord);
            }
        }
    }
    initializeGrid();
    setupEventListeners();
}
